// Milestone 10: the ~395 extra buy-mode designs, one file per group so that several people can add designs at the same time
// without touching each other's files. Per group:
//   <group>.ts          the ObjectDef list: `export default function (k: ObjectKit): ObjectDef[]` (written by hand)
//   <group>.models.ts   measured model bounds and screen rectangles (GENERATED by `node tools/build-extra-furniture.mjs`)
// The models themselves are tools/furniture-extra/m10/<group>.mjs. Authoring guide: dev/ds-tasks/m10f/AUTHORING.md.
// objects.ts calls every builder with its helper kit and appends the result to OBJECTS; MODEL_BOUNDS gets the generated bounds.

import type { ObjectDef } from '../types';
import type { ObjectKit } from '../objects';
import type { M10ModelInfo } from './modelInfo';
import decorHobby from './decor-hobby';
import { MODELS as decorHobbyModels } from './decor-hobby.models';
import kitchenBathElectronics from './kitchen-bath-electronics';
import { MODELS as kitchenBathElectronicsModels } from './kitchen-bath-electronics.models';
import lightingOutdoorKids from './lighting-outdoor-kids';
import { MODELS as lightingOutdoorKidsModels } from './lighting-outdoor-kids.models';
import seatingBeds from './seating-beds';
import { MODELS as seatingBedsModels } from './seating-beds.models';
import tablesStorage from './tables-storage';
import { MODELS as tablesStorageModels } from './tables-storage.models';

export type GroupBuilder = (k: ObjectKit) => ObjectDef[];

/** Group name (the file name) -> builder, in catalog order. */
export const M10_BUILDERS: Record<string, GroupBuilder> = {
  'seating-beds': seatingBeds,
  'tables-storage': tablesStorage,
  'kitchen-bath-electronics': kitchenBathElectronics,
  'lighting-outdoor-kids': lightingOutdoorKids,
  'decor-hobby': decorHobby,
};

const GROUP_MODELS: Record<string, Record<string, M10ModelInfo>> = {
  'seating-beds': seatingBedsModels,
  'tables-storage': tablesStorageModels,
  'kitchen-bath-electronics': kitchenBathElectronicsModels,
  'lighting-outdoor-kids': lightingOutdoorKidsModels,
  'decor-hobby': decorHobbyModels,
};

/** Every generated model record by asset name. A model in two groups is a hard error. */
export const M10_MODELS: Record<string, M10ModelInfo> = {};
for (const [group, models] of Object.entries(GROUP_MODELS)) {
  for (const [name, info] of Object.entries(models)) {
    if (name in M10_MODELS) throw new Error(`objectsM10: model '${name}' appears in two groups (second: ${group})`);
    M10_MODELS[name] = info;
  }
}
